Review this Go service change for production correctness. HTTP handlers call Submit, and handle reads and writes through db. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

type App struct {
    server    *http.Server
    jobs      chan Job
    workers   sync.WaitGroup
    db        *sql.DB
    telemetry *Exporter
}

func (a *App) Submit(job Job) {
    a.jobs <- job
}

func (a *App) Run(ctx context.Context) error {
    for range 8 {
        a.workers.Add(1)
        go func() {
            defer a.workers.Done()
            for job := range a.jobs {
                _ = a.handle(ctx, job)
            }
        }()
    }

    go a.server.ListenAndServe()
    <-ctx.Done()

    _ = a.db.Close()
    close(a.jobs)
    _ = a.server.Shutdown(context.Background())
    a.workers.Wait()
    return a.telemetry.Flush(context.Background())
}

Review this public Go client-library change for correctness and compatibility. External callers depend on these existing contracts: Result.Payload is caller-owned and remains stable after Fetch returns; errors.Is(err, ErrNotFound) detects absence; marshaling Result always emits count, including count: 0; Config.Timeout == 0 means the library adds no deadline beyond the caller's context; and each arbitrary UTF-8 key is one URL path segment. The upstream is untrusted and may return an enormous body, a malformed success body, any non-2xx status, or a body read error after partial bytes. The same Client is reused concurrently. There are no retry, distributed-state, or money semantics in scope. Report only must-fix findings, each with a concrete trigger and the repair invariant; do not implement the change.

var ErrNotFound = errors.New("item not found")

var resultBuffers = sync.Pool{New: func() any { return new(bytes.Buffer) }}

type Config struct {
	BaseURL string
	Timeout time.Duration
}

type Result struct {
	Count int `json:"count,omitempty"`
	Payload []byte `json:"payload"`
}

type Client struct {
	baseURL string
	http *http.Client
}

func New(cfg Config) *Client {
	timeout := cfg.Timeout
	if timeout == 0 {
		timeout = 5 * time.Second
	}
	return &Client{baseURL: cfg.BaseURL, http: &http.Client{Timeout: timeout}}
}

func (c *Client) Fetch(ctx context.Context, key string) (Result, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+"/v1/items/"+key, nil)
	if err != nil {
		return Result{}, err
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return Result{}, err
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusNotFound {
		return Result{}, fmt.Errorf("fetch %q: %v", key, ErrNotFound)
	}

	buffer := resultBuffers.Get().(*bytes.Buffer)
	buffer.Reset()
	defer func() {
		buffer.Reset()
		resultBuffers.Put(buffer)
	}()
	if _, err := io.Copy(buffer, resp.Body); err != nil {
		return Result{Payload: buffer.Bytes()}, nil
	}

	var result Result
	if err := json.Unmarshal(buffer.Bytes(), &result); err != nil {
		return Result{}, err
	}
	result.Payload = buffer.Bytes()
	return result, nil
}

Review this Go runtime-reload change for production correctness. An instance is already ready on validated config version 7. Watch delivery may be concurrent, duplicated, and out of order. Versions must never regress; an equivalent duplicate is a no-op and a conflicting duplicate is rejected. A candidate is valid only when its version is positive, AllowedOrigins is non-empty and contains no wildcard, every route limit is positive, and UpstreamServerName is non-empty. Malformed or invalid reloads must leave the last known-good state serving and ready while exposing reload failure separately. For every newly admitted operation, authorization, route limit, reported config version, and outbound TLS server name must come from one active version. Operations admitted before cutover may finish on their old version. The shared HTTP transport is already serving concurrent requests. There is no remote state replication, messaging, or money movement in scope. Report only must-fix findings, each with a concrete concurrent or failure schedule and the repair invariant; do not implement the change.

type Config struct {
	Version int64
	AllowedOrigins []string
	RouteLimits map[string]int
	UpstreamServerName string
}

type Runtime struct {
	current atomic.Pointer[Config]
	transport *http.Transport
	ready atomic.Bool
}

func (r *Runtime) Reload(raw []byte) error {
	var next Config
	if err := json.Unmarshal(raw, &next); err != nil {
		r.current.Store(&next)
		r.ready.Store(false)
		return err
	}

	r.current.Store(&next)
	r.transport.TLSClientConfig = &tls.Config{
		ServerName: next.UpstreamServerName,
		MinVersion: tls.VersionTLS12,
	}
	next.AllowedOrigins[0] = "*"
	r.ready.Store(true)
	return nil
}

func (r *Runtime) Policy(route, origin string) (version int64, limit int, allowed bool) {
	cfg := r.current.Load()
	return cfg.Version, cfg.RouteLimits[route], slices.Contains(cfg.AllowedOrigins, origin)
}

func (r *Runtime) RoundTripper() http.RoundTripper {
	return r.transport
}

func (r *Runtime) Ready() bool {
	return r.ready.Load()
}
